final class VaultRenderingTest {
    private static final BlockPos SMALL=new BlockPos(1500,4,5),MEDIUM=new BlockPos(1506,4,5),LARGE=new BlockPos(1512,4,5),CRATE=new BlockPos(1522,4,5);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var hidden=new AtomicBoolean();context.runOnClient(client->{hidden.set(client.gui.hud.isHidden());if(hidden.get())client.gui.hud.toggle();});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1515 10 14");context.waitFor(client->Math.abs(client.player.getX()-1515.5)<.1,300);waitChunks(context,world,new BlockPos(1496,3,0),new BlockPos(1535,3,15));NativeScreenshotReadiness.beforeFloor(context, world, new BlockPos(1496, 3, 0), new BlockPos(1535, 3, 15), SMALL, MEDIUM, LARGE, CRATE);
        server.runCommand("fill 1496 3 0 1535 3 15 minecraft:smooth_quartz");
        NativeScreenshotReadiness.afterFloor(context, world, new BlockPos(1496, 3, 0), new BlockPos(1535, 3, 15));
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();place(level,SMALL,1,3,Direction.Axis.X);place(level,MEDIUM,2,3,Direction.Axis.X);place(level,LARGE,3,4,Direction.Axis.X);place(level,new BlockPos(1496,4,7),2,4,Direction.Axis.Z);level.setBlockAndUpdate(CRATE,AllBlocks.CREATIVE_CRATE.defaultBlockState());});
        context.waitFor(client->client.level.getBlockEntity(LARGE) instanceof ItemVaultBlockEntity vault&&vault.getWidth()==3&&vault.getHeight()==4&&client.level.getBlockEntity(MEDIUM) instanceof ItemVaultBlockEntity medium&&medium.getWidth()==2,300);world.getConnection().waitForChunksRender();context.getInput().lookAt(new BlockPos(1512,5,5));
        context.runOnClient(client->{for(var pos:List.of(SMALL,MEDIUM,LARGE,new BlockPos(1496,4,7))){var block=client.level.getBlockState(pos);var model=client.getModelManager().getBlockStateModelSet().get(block);var mesh=net.fabricmc.fabric.api.client.renderer.v1.Renderer.get().mutableMesh();model.emitQuads(mesh.emitter(),(net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,pos,block,net.minecraft.util.RandomSource.create(42),face->false);if(mesh.immutableCopy().size()!=3&&pos!=SMALL)throw new AssertionError("Vault CT must cull three interior faces at a corner: "+pos+" -> "+mesh.immutableCopy().size());if(!(model instanceof ItemVaultModel))throw new AssertionError("Native vault model wrapper missing");}});context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-vault-sizes-connected-textures");
        server.runCommand("tp @p 1522 4 9");context.waitFor(client->Math.abs(client.player.getX()-1522.5)<.1&&client.level.getBlockState(new BlockPos(1522,3,9)).is(Blocks.SMOOTH_QUARTZ),300);world.getConnection().waitForChunksRender();server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.resetFallDistance();player.setHealth(player.getMaxHealth());});server.runCommand("gamemode survival @p");server.runCommand("item replace entity @p weapon.mainhand with minecraft:apple 8");context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().is(Items.APPLE),200);lookAt(context,CreativeCrateBlock.FILTER_POSITION.add(Vec3.atLowerCornerOf(CRATE)));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(CRATE)&&CreativeCrateBlock.testFilterHit(CRATE,hit),200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.level.getBlockEntity(CRATE) instanceof CreativeCrateBlockEntity crate&&crate.filtering.getFilter().is(Items.APPLE),200);context.runOnClient(client->{if(client.player.getMainHandItem().getCount()!=8)throw new AssertionError("Creative crate sample consumed apples");var rendered=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(CRATE),.5f,null,false);if(!(rendered instanceof CreativeCrateRenderer.State state)||state.sample.isEmpty())throw new AssertionError("Creative crate sample was not extracted");});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1522 7 8");context.waitFor(client->Math.abs(client.player.getY()-7)<.1,200);lookAt(context,CreativeCrateBlock.FILTER_POSITION.add(Vec3.atLowerCornerOf(CRATE)));context.waitTicks(4);context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-creative-crate-supply-sample");
        server.runOnServer(ignored->{var crate=(CreativeCrateBlockEntity)world.getConnection().getServerLevel().getBlockEntity(CRATE);for(int i=0;i<2;i++)try(var tx=Transaction.openOuter()){if(crate.inv.extract(ItemVariant.of(Items.APPLE),64,tx)!=64)throw new AssertionError("Creative supply depleted");tx.commit();}});
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{var rendered=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(CRATE),.5f,null,false);if(!(rendered instanceof CreativeCrateRenderer.State state)||state.sample.isEmpty())throw new AssertionError("Crate sample missing after resource reload");});server.runCommand("gamemode spectator @p");chunkUnload(context,world);chestChunkUnload(context,world);context.runOnClient(client->{if(client.gui.hud.isHidden()!=hidden.get())client.gui.hud.toggle();});
    }
    private static void place(net.minecraft.server.level.ServerLevel level,BlockPos origin,int width,int length,Direction.Axis axis){for(int along=0;along<length;along++)for(int x=0;x<width;x++)for(int y=0;y<width;y++){var pos=axis==Direction.Axis.X?origin.offset(along,x,y):origin.offset(x,y,along);level.setBlockAndUpdate(pos,AllBlocks.ITEM_VAULT.defaultBlockState().setValue(ItemVaultBlock.HORIZONTAL_AXIS,axis));}}
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var origin=new BlockPos(1550,4,5);server.runCommand("tp @p 1551 9 12");context.waitFor(client->Math.abs(client.player.getX()-1551.5)<.1,300);waitChunks(context,world,origin,origin.east(2));
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();place(level,origin,1,3,Direction.Axis.X);});context.waitFor(client->client.level.getBlockEntity(origin) instanceof ItemVaultBlockEntity vault&&vault.getHeight()==3,300);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var root=(ItemVaultBlockEntity)level.getBlockEntity(origin);try(var tx=Transaction.openOuter()){if(root.storage().insert(ItemVariant.of(Items.DIAMOND),1287,tx)!=1287)throw new AssertionError("Boundary vault test fill failed");tx.commit();}level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(origin.getX()>>4,origin.getZ()>>4));});
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();var oldView=new AtomicReference<net.fabricmc.fabric.api.transfer.v1.storage.StorageView<ItemVariant>>();
        for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var root=(ItemVaultBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,origin);if(root!=null){if(oldView.get()==null){var iterator=root.storage().iterator();if(iterator.hasNext())oldView.set(iterator.next());}try(var tx=Transaction.openOuter()){root.storage().extract(ItemVariant.of(Items.DIAMOND),1,tx);}}unloaded.set(!level.isLoaded(origin.east(2)));});}if(!unloaded.get())throw new AssertionError("Vault storage kept neighboring chunk loaded");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var root=(ItemVaultBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,origin);try(var tx=Transaction.openOuter()){if(root.storage().extract(ItemVariant.of(Items.DIAMOND),1,tx)!=0||root.storage().insert(ItemVariant.of(Items.APPLE),1,tx)!=0)throw new AssertionError("Partially unloaded vault exposed combined inventory");if(oldView.get()!=null&&oldView.get().extract(ItemVariant.of(Items.DIAMOND),1,tx)!=0)throw new AssertionError("Held view bypassed chunk availability");}level.setBlockAndUpdate(origin,Blocks.AIR.defaultBlockState());});
        server.runCommand("tp @p 1551 9 12");context.waitFor(client->Math.abs(client.player.getX()-1551.5)<.1&&client.level.getBlockEntity(origin.east(2)) instanceof ItemVaultBlockEntity,400);context.waitTicks(20);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var survivors=new HashSet<BlockPos>();long amount=0;for(var pos:List.of(origin.east(),origin.east(2))){var vault=(ItemVaultBlockEntity)level.getBlockEntity(pos);var master=vault.getControllerBE();if(master!=null&&survivors.add(master.getBlockPos()))for(var view:master.storage())if(view.getResource().equals(ItemVariant.of(Items.DIAMOND)))amount+=view.getAmount();}if(amount!=7)throw new AssertionError("Vault split across unloaded chunk lost survivor contents: "+amount);long drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(origin).inflate(3)).stream().filter(entity->entity.getItem().is(Items.DIAMOND)).mapToLong(entity->entity.getItem().getCount()).sum();if(drops!=1280)throw new AssertionError("Removed component contents dropped incorrectly: "+drops);level.getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(origin.getX()>>4,origin.getZ()>>4),0);});context.getInput().lookAt(origin.east());world.getConnection().waitForChunksRender();context.takeScreenshot("create-vulkan-vault-after-unloaded-controller-removal");
    }
    private static void chestChunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var west=new BlockPos(1567,4,5);var east=west.east();var held=new AtomicReference<Storage<ItemVariant>>();var view=new AtomicReference<StorageView<ItemVariant>>();
        server.runCommand("tp @p 1567 9 12");context.waitFor(client->Math.abs(client.player.getX()-1567.5)<.1,300);waitChunks(context,world,west,east);
        server.runOnServer(ignored->{
            var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(west,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.LEFT));level.setBlockAndUpdate(east,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.RIGHT));
            ((ChestBlockEntity)level.getBlockEntity(west)).setItem(0,new ItemStack(Items.DIAMOND,11));((ChestBlockEntity)level.getBlockEntity(east)).setItem(0,new ItemStack(Items.DIAMOND,13));held.set(FunnelTransfer.find(level,west,Direction.DOWN));for(var candidate:held.get())if(!candidate.isResourceBlank()){view.set(candidate);break;}if(view.get()==null)throw new AssertionError("Chest held-view fixture missing");
            level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(west.getX()>>4,west.getZ()>>4));
        });
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();
        for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var storage=FunnelTransfer.find(level,west,Direction.DOWN);if(storage==null)throw new AssertionError("Held owner chunk must stay FULL");InventoryIdentifier.get(level,new BlockFace(west,Direction.DOWN));try(var tx=Transaction.openOuter()){storage.extract(ItemVariant.of(Items.DIAMOND),1,tx);view.get().extract(ItemVariant.of(Items.DIAMOND),1,tx);}unloaded.set(!level.isLoaded(east));});}
        if(!unloaded.get())throw new AssertionError("Double chest storage renewed neighboring chunk tickets");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();if(LoadedLevelAccess.blockEntity(level,west)==null)throw new AssertionError("West chest unexpectedly unloaded");if(InventoryIdentifier.get(level,new BlockFace(east,Direction.UP))!=null)throw new AssertionError("Unloaded chest got an inventory identifier");try(var tx=Transaction.openOuter()){if(held.get().extract(ItemVariant.of(Items.DIAMOND),1,tx)!=0||held.get().insert(ItemVariant.of(Items.APPLE),1,tx)!=0||view.get().extract(ItemVariant.of(Items.DIAMOND),1,tx)!=0)throw new AssertionError("Partially unloaded double chest exposed contents");}if(!view.get().isResourceBlank()||view.get().getAmount()!=0)throw new AssertionError("Held chest view exposed an unloaded inventory");});
        server.runCommand("tp @p 1567 9 12");context.waitFor(client->Math.abs(client.player.getX()-1567.5)<.1&&client.level.getBlockEntity(east) instanceof ChestBlockEntity,400);waitChunks(context,world,west,east);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();try(var tx=Transaction.openOuter()){if(held.get().extract(ItemVariant.of(Items.DIAMOND),24,tx)!=24)throw new AssertionError("Chest lookup did not recover after reload");}if(((ChestBlockEntity)LoadedLevelAccess.blockEntity(level,west)).getItem(0).getCount()!=11||((ChestBlockEntity)LoadedLevelAccess.blockEntity(level,east)).getItem(0).getCount()!=13)throw new AssertionError("Chest unload changed per-half item ownership");level.getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(west.getX()>>4,west.getZ()>>4),0);});
    }
    private static void waitChunks(ClientGameTestContext context,TestSingleplayerContext world,BlockPos first,BlockPos last){var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){world.getServer().runOnServer(ignored->{var level=world.getConnection().getServerLevel();ready.set(level.hasChunkAt(first)&&level.hasChunkAt(last));});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Vault scene chunks did not load");}
    private static void lookAt(ClientGameTestContext context,Vec3 point){var rotation=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y);}
}
